<?php
declare(strict_types=1);

/** Двухшаговое восстановление всей таблицы kiosks из закрытой JSON-копии. */
require_once dirname(__DIR__) . '/include/app.php';require_once dirname(__DIR__) . '/include/kiosk_admin.php';require_once dirname(__DIR__) . '/include/admin_security.php';app_require_admin();if(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);exit;}app_require_csrf();$action=(string)($_POST['action']??'preview');app_require_admin_password();
function backup_path(string $name):string{if(preg_match('/^kiosks-before-[a-z0-9-]+-\d{8}-\d{6}-[a-f0-9]{6}\.json$/',$name)!==1)throw new InvalidArgumentException('Недопустимое имя копии.');$directory=realpath(dirname(__DIR__,2).'/private/runtime/backups');$path=$directory?realpath($directory.'/'.$name):false;if(!$directory||!$path||dirname($path)!==$directory||!is_file($path))throw new InvalidArgumentException('Копия не найдена.');return $path;}
if($action==='confirm'){$token=(string)($_POST['restore_token']??'');$state=$_SESSION['restore_preview']??null;if(!is_array($state)||!hash_equals((string)($state['token']??''),$token)||(int)($state['created_at']??0)<time()-600){http_response_code(422);exit('Предпросмотр устарел.');}try{$body=json_decode((string)file_get_contents(backup_path((string)$state['name'])),true,512,JSON_THROW_ON_ERROR);$rows=$body['kiosks']??[];if(!is_array($rows)||!$rows)throw new InvalidArgumentException('В копии нет автоматов.');$pdo=app_pdo();$pdo->beginTransaction();app_kiosk_backup($pdo,'before-restore');$pdo->exec('DELETE FROM kiosks');$insert=$pdo->prepare('INSERT INTO kiosks (id,machine_number,address,area,latitude,longitude,status,schedule,metro,landmark,photo_url,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($rows as $row){$data=app_kiosk_form_data($row);$allowedStatuses=['active','maintenance','planned','hidden'];$status=in_array((string)($row['status']??''),$allowedStatuses,true)?(string)$row['status']:'active';$insert->execute([(int)$row['id'],$data['number'],$data['address'],$data['area'],$data['latitude'],$data['longitude'],$status,$data['schedule'],$data['metro'],$data['landmark'],(string)($row['photo_url']??''),(string)($row['created_at']??date('Y-m-d H:i:s')),(string)($row['updated_at']??date('Y-m-d H:i:s'))]);app_kiosk_store_version($pdo,(int)$row['id'],'full-restore');}$pdo->commit();unset($_SESSION['restore_preview']);app_kiosk_clear_api_cache();header('Location: /admin/backups.php?restored='.count($rows));exit;}catch(InvalidArgumentException $error){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();http_response_code(422);exit(app_h($error->getMessage()));}catch(Throwable $error){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();error_log('kioskvoda_admin restore_failed');http_response_code(500);exit('Восстановление не выполнено.');}}
try{$name=(string)($_POST['name']??'');$body=json_decode((string)file_get_contents(backup_path($name)),true,512,JSON_THROW_ON_ERROR);$backupRows=is_array($body['kiosks']??null)?$body['kiosks']:[];$current=app_pdo()->query('SELECT * FROM kiosks')->fetchAll();$old=[];foreach($backupRows as $row)$old[(int)$row['id']]=$row;$now=[];foreach($current as $row)$now[(int)$row['id']]=$row;$added=count(array_diff_key($old,$now));$removed=count(array_diff_key($now,$old));$changed=0;foreach(array_intersect_key($old,$now) as $id=>$row)if(json_encode($row)!==json_encode($now[$id]))$changed++;$token=bin2hex(random_bytes(24));$_SESSION['restore_preview']=['token'=>$token,'name'=>$name,'created_at'=>time()];}catch(Throwable $error){http_response_code(422);exit('Не удалось прочитать резервную копию.');}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Восстановление — Киосквода</title><link rel="stylesheet" href="/css/admin.css?v=20260816-6"></head><body><header class="admin-header"><div><strong>Киосквода</strong><span>Предпросмотр восстановления</span></div><nav><a href="/admin/backups.php">Отменить</a></nav></header><main class="admin-page"><div class="admin-page__heading"><div><p>Копия <?=app_h((string)($body['created_at']??''))?></p><h1>Что изменится</h1></div><span><?=count($backupRows)?> автоматов в копии</span></div><div class="import-summary"><div><strong><?=$added?></strong><span>вернётся из копии</span></div><div><strong><?=$changed?></strong><span>будет заменено</span></div><div class="has-errors"><strong><?=$removed?></strong><span>отсутствует в копии</span></div></div><form class="confirm-bar" method="post" onsubmit="return confirm('Восстановить всю таблицу? Текущие данные сначала сохранятся в новую копию.');"><input type="hidden" name="csrf" value="<?=app_h(app_csrf())?>"><input type="hidden" name="action" value="confirm"><input type="hidden" name="restore_token" value="<?=app_h($token)?>"><a href="/admin/backups.php">Отменить</a><button class="danger">Восстановить копию</button></form></main></body></html>
